window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c1f0c75a4c05387f"]={"versions": [{"id": "FIG-c1f0c75a4c05387f", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des dynamischen Verhaltens bei der BusOff-Behandlung innerhalb des AUTOSAR Classic Platform Communication Stacks (Can-Treiber, CanIf und obere Schichten/Nutzer-Callbacks).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>«interface» CanIf_User_Cbk</code>: Callback-Schnittstelle zu übergeordneten Schichten (z. B. CanSM).\n</li><li><code>«module» CanIf</code>: AUTOSAR CAN Interface Modul.\n</li><li><code>«module» Can</code>: AUTOSAR CAN Driver Modul (gekennzeichnet mit Unendlich-Symbol für asynchrone/wiederholende Verarbeitung).\n</li><li><code>«Peripheral» CanController</code>: Hardwarenaher CAN-Controller.\n</li></ul>\n<p class=\"fig-p\">Aufrufe und Schnittstellenfunktionen:</p>\n<ul class=\"fig-list\"><li><code>BusOff Detection()</code>\n</li><li><code>Set CAN Controller to STOPPED mode, if necessary()</code>\n</li><li><code>CanIf_ControllerBusOff(uint8)</code>\n</li><li><code>Change to CANIF_CS_STOPPED()</code>\n</li><li><code>Reset transmit queue()</code>\n</li><li><code>&lt;User_ControllerBusOff&gt;(uint8)</code>\n</li><li>Rückgabesignale: <code>&lt;User_ControllerBusOff&gt;()</code>, <code>CanIf_ControllerBusOff()</code>, <code>BusOff Detection()</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>CanController</code> erkennt einen BusOff-Zustand (<code>BusOff Detection()</code>) und meldet diesen an das Modul <code>Can</code>.\n</li><li>Das Modul <code>Can</code> setzt den Controller bei Bedarf in den Modus STOPPED (<code>Set CAN Controller to STOPPED mode, if necessary()</code>), bestätigt durch die Hardware.\n</li><li>Das Modul <code>Can</code> ruft <code>CanIf_ControllerBusOff(uint8)</code> auf dem <code>CanIf</code> auf (unter Übergabe der Controller-ID).\n</li><li><code>CanIf</code> führt interne Zustandsübergänge durch:\n<ul class=\"fig-list\"><li>Wechselt den Zustand auf <code>CANIF_CS_STOPPED</code> (<code>Change to CANIF_CS_STOPPED()</code>).\n</li><li>Setzt die Sendewarteschlangen zurück (<code>Reset transmit queue()</code>), annotiert mit dem Kommentar: „Transmit queues being reset to avoid transmission of old L-PDUs after CAN controller restart“.\n</li></ul>\n</li><li><code>CanIf</code> leitet das Ereignis über <code>&lt;User_ControllerBusOff&gt;(uint8)</code> an den konfigurierten Callback-Empfänger (<code>CanIf_User_Cbk</code>) weiter.\n</li><li>Die Aufrufkette kehrt synchron zurück (<code>&lt;User_ControllerBusOff&gt;()</code> -&gt; <code>CanIf_ControllerBusOff()</code> -&gt; <code>BusOff Detection()</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Zurücksetzen der Transmit-Queues (<code>Reset transmit queue()</code>) stellt sicher, dass nach einem BusOff und anschließendem Neustart des CAN-Controllers keine veralteten L-PDUs übertragen werden.\n</li><li>Die Benachrichtigung der oberen Schicht (<code>&lt;User_ControllerBusOff&gt;</code>) muss den betroffenen CAN-Controller via <code>uint8</code>-Parameter identifizieren.\n</li><li>Der Wechsel in <code>CANIF_CS_STOPPED</code> muss im <code>CanIf</code> vor dem Verarbeiten weiterer Anfragen oder dem Abschluss des Callbacks erfolgen.\n</li></ul>"}, {"id": "FIG-6b0d19472d711d30", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des dynamischen Verhaltens bei der BusOff-Behandlung innerhalb des AUTOSAR Classic Platform Communication Stacks (Can-Treiber, CanIf und obere Schichten/Nutzer-Callbacks).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>«interface» CanIf_User_Cbk</code>: Callback-Schnittstelle zu übergeordneten Schichten (z. B. CanSM).\n</li><li><code>«module» CanIf</code>: AUTOSAR CAN Interface Modul.\n</li><li><code>«module» Can</code>: AUTOSAR CAN Driver Modul (gekennzeichnet mit Unendlich-Symbol für asynchrone/wiederholende Verarbeitung).\n</li><li><code>«Peripheral» CanController</code>: Hardwarenaher CAN-Controller.\n</li></ul>\n<p class=\"fig-p\">Aufrufe und Schnittstellenfunktionen:</p>\n<ul class=\"fig-list\"><li><code>BusOff Detection()</code>\n</li><li><code>Set CAN Controller to STOPPED mode, if necessary()</code>\n</li><li><code>CanIf_ControllerBusOff(uint8)</code>\n</li><li><code>Change to CANIF_CS_STOPPED()</code>\n</li><li><code>Reset transmit queue()</code>\n</li><li><code>&lt;User_ControllerBusOff&gt;(uint8)</code>\n</li><li>Rückgabesignale: <code>&lt;User_ControllerBusOff&gt;()</code>, <code>CanIf_ControllerBusOff()</code>, <code>BusOff Detection()</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>CanController</code> erkennt einen BusOff-Zustand (<code>BusOff Detection()</code>) und meldet diesen an das Modul <code>Can</code>.\n</li><li>Das Modul <code>Can</code> setzt den Controller bei Bedarf in den Modus STOPPED (<code>Set CAN Controller to STOPPED mode, if necessary()</code>), bestätigt durch die Hardware.\n</li><li>Das Modul <code>Can</code> ruft <code>CanIf_ControllerBusOff(uint8)</code> auf dem <code>CanIf</code> auf (unter Übergabe der Controller-ID).\n</li><li><code>CanIf</code> führt interne Zustandsübergänge durch:\n<ul class=\"fig-list\"><li>Wechselt den Zustand auf <code>CANIF_CS_STOPPED</code> (<code>Change to CANIF_CS_STOPPED()</code>).\n</li><li>Setzt die Sendewarteschlangen zurück (<code>Reset transmit queue()</code>), annotiert mit dem Kommentar: „Transmit queues being reset to avoid transmission of old L-PDUs after CAN controller restart“.\n</li></ul>\n</li><li><code>CanIf</code> leitet das Ereignis über <code>&lt;User_ControllerBusOff&gt;(uint8)</code> an den konfigurierten Callback-Empfänger (<code>CanIf_User_Cbk</code>) weiter.\n</li><li>Die Aufrufkette kehrt synchron zurück (<code>&lt;User_ControllerBusOff&gt;()</code> -&gt; <code>CanIf_ControllerBusOff()</code> -&gt; <code>BusOff Detection()</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Zurücksetzen der Transmit-Queues (<code>Reset transmit queue()</code>) stellt sicher, dass nach einem BusOff und anschließendem Neustart des CAN-Controllers keine veralteten L-PDUs übertragen werden.\n</li><li>Die Benachrichtigung der oberen Schicht (<code>&lt;User_ControllerBusOff&gt;</code>) muss den betroffenen CAN-Controller via <code>uint8</code>-Parameter identifizieren.\n</li><li>Der Wechsel in <code>CANIF_CS_STOPPED</code> muss im <code>CanIf</code> vor dem Verarbeiten weiterer Anfragen oder dem Abschluss des Callbacks erfolgen.\n</li></ul>"}], "trans": [{"from": "FIG-c1f0c75a4c05387f", "to": "FIG-6b0d19472d711d30", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
